package net.officefloor.hq.app.plan;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.role.SheetRole;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.server.ResponseStatusException;

/** The plans people on a sheet have, and the draft claims they make. */
@Service
public class PlanService {

    private final PlanRepository plans;
    private final PersonRepository people;
    private final ClaimService claims;
    private final SheetService sheets;
    private final TransactionTemplate transaction;
    private final Audit audit;
    private final RoleService roles;

    public PlanService(PlanRepository plans, PersonRepository people, ClaimService claims, SheetService sheets,
            PlatformTransactionManager transactions, Audit audit, RoleService roles) {
        this.plans = plans;
        this.people = people;
        this.claims = claims;
        this.sheets = sheets;
        this.transaction = new TransactionTemplate(transactions);
        this.audit = audit;
        this.roles = roles;
    }

    /** The plans on the sheet in the order they were added. */
    @Transactional(readOnly = true)
    public List<Plan> list(String sheetId) {
        return plans.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** Add a plan for a person, repeating either every so many days or monthly on a day of the month;
     *  a start left out takes the sheet's today. Refused for an amount that is not above zero, neither
     *  or both of an interval and a day, an interval below one day, a day outside 1 to 31, and an end
     *  before the start. */
    @Transactional
    public Plan add(String sheetId, String user, long personId, BigDecimal amount, LocalDate start, Integer every,
            Integer day, LocalDate end) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
        if (amount.signum() <= 0) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A plan's amount must be above zero");
        }
        if ((every == null) == (day == null)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
                    "A plan repeats either every so many days or on a day of the month");
        }
        if (day != null && (day < 1 || day > 31)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A plan's day of the month is 1 to 31");
        }
        if (every != null && every < 1) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A plan repeats every one day or more");
        }
        LocalDate from = start != null ? start : sheets.today(sheetId);
        if (end.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A plan cannot end before it starts");
        }
        Plan saved = plans.saveAndFlush(new Plan(sheetId, person.getId(), amount, from, every, day, end));
        audit.recordOnCommit("PLAN_ADDED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " amount=" + amount.setScale(2).toPlainString() + " start=" + from
                + (day != null ? " day=" + day : " every=" + every) + " end=" + end);
        return saved;
    }

    /** Pause the plan from the sheet's today, or resume it on that day; refused for pausing a paused
     *  plan or resuming one that is not paused. */
    @Transactional
    public Plan setPaused(String sheetId, String user, long planId, boolean paused) {
        Plan plan = plans.findById(planId).filter(p -> p.getSheetId().equals(sheetId))
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such plan on this sheet"));
        if (plan.isPaused() == paused) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    paused ? "The plan is already paused" : "The plan is not paused");
        }
        Person person = people.findByIdAndSheetId(plan.getPersonId(), sheetId).orElseThrow();
        LocalDate today = sheets.today(sheetId);
        if (paused) {
            plan.pause(today);
        } else {
            plan.resume(today);
        }
        Plan saved = plans.saveAndFlush(plan);
        audit.recordOnCommit((paused ? "PLAN_PAUSED" : "PLAN_RESUMED") + " sheet=" + sheetId + " by=" + user
                + " name=" + person.getName() + " start=" + plan.getStartDate());
        return saved;
    }

    /** Change the plan's amount from the sheet's today: the claims it makes from then on take it,
     *  those it has made keep theirs. Refused for an amount that is not above zero. */
    @Transactional
    public Plan changeAmount(String sheetId, String user, long planId, BigDecimal amount) {
        Plan plan = plans.findById(planId).filter(p -> p.getSheetId().equals(sheetId))
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such plan on this sheet"));
        if (amount.signum() <= 0) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A plan's amount must be above zero");
        }
        Person person = people.findByIdAndSheetId(plan.getPersonId(), sheetId).orElseThrow();
        plan.changeAmount(sheets.today(sheetId), amount);
        Plan saved = plans.saveAndFlush(plan);
        audit.recordOnCommit("PLAN_CHANGED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " start=" + plan.getStartDate() + " amount=" + amount.setScale(2).toPlainString());
        return saved;
    }

    /** Make, for every plan on the sheet in the order they were added, a draft claim of its amount
     *  with an empty note for each of its dates up to its end and the sheet's today that has none
     *  yet, oldest first. Each claim is added as the claim form adds it, in a transaction of its
     *  own: a date the form refuses is skipped, and tried again by the next generate. Returns how
     *  many claims were made. A viewer's generate makes none. */
    public int generate(String sheetId, String user) {
        if (SheetRole.VIEWER.equals(roles.roleOf(sheetId, user))) {
            return 0;
        }
        LocalDate today = sheets.today(sheetId);
        int made = 0;
        for (Plan plan : plans.findBySheetIdOrderByIdAsc(sheetId)) {
            for (LocalDate date : plan.dueUpTo(today)) {
                try {
                    transaction.executeWithoutResult(status -> {
                        Plan locked = plans.findById(plan.getId()).orElseThrow();
                        if (!locked.dueUpTo(date).contains(date)) {
                            return;
                        }
                        claims.add(sheetId, user, locked.getPersonId(), locked.getAmount(), date, "");
                        locked.markMade(date);
                        plans.saveAndFlush(locked);
                    });
                    made++;
                } catch (ResponseStatusException refused) {
                    // the claim form refused the date: it is tried again next time
                }
            }
        }
        return made;
    }
}
package net.officefloor.hq.app.plan;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.role.ViewerAllowed;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}")
@Validated
public class PlanController {

    /** What the screen shows of a plan: its amount as text with two decimals, its dates, its interval
     *  or day of the month (the other null), how many claims it has made so far, and its next dates:
     *  the first five after the sheet's today and on or before its end; whether it is paused; and the
     *  changes of its amount, oldest first. */
    public record PlanView(long id, long personId, String amount, LocalDate start, Integer every, Integer day,
            LocalDate end, int generated, List<LocalDate> nextDates, boolean paused, List<ChangeView> changes) {
        static PlanView of(Plan plan, LocalDate today) {
            return new PlanView(plan.getId(), plan.getPersonId(), plan.getAmount().setScale(2).toPlainString(),
                    plan.getStartDate(), plan.getEveryDays(), plan.getMonthDay(), plan.getEndDate(),
                    plan.getGenerated(), plan.nextAfter(today, 5), plan.isPaused(),
                    plan.getChanges().stream().map(ChangeView::of).toList());
        }
    }

    /** A change of a plan's amount: the day it was changed on and the new amount as text with two decimals. */
    public record ChangeView(LocalDate on, String amount) {
        static ChangeView of(PlanChange change) {
            return new ChangeView(change.getChangedOn(), change.getAmount().setScale(2).toPlainString());
        }
    }

    /** The plan's new amount: required, with up to two decimals. */
    public record AmountForm(@NotNull @Pattern(regexp = "\\s*\\d{1,12}(\\.\\d{1,2})?\\s*") String amount) {

        BigDecimal amountValue() {
            return new BigDecimal(amount.trim()).setScale(2);
        }
    }

    /** The plan form: a required amount with up to two decimals, an optional start (the sheet's today
     *  when left out), either a whole number of days it repeats every or a day of the month it falls
     *  on (the other blank), and a required end. */
    public record PlanForm(@NotNull @Pattern(regexp = "\\s*\\d{1,12}(\\.\\d{1,2})?\\s*") String amount,
            LocalDate start, @Pattern(regexp = "\\s*(\\d{1,5})?\\s*") String every,
            @Pattern(regexp = "\\s*(\\d{1,2})?\\s*") String day, @NotNull LocalDate end) {

        BigDecimal amountValue() {
            return new BigDecimal(amount.trim()).setScale(2);
        }

        Integer everyValue() {
            return every == null || every.isBlank() ? null : Integer.valueOf(every.trim());
        }

        Integer dayValue() {
            return day == null || day.isBlank() ? null : Integer.valueOf(day.trim());
        }
    }

    /** How many claims a generate made. */
    public record Generated(int made) {
    }

    private final PlanService service;
    private final SheetService sheets;

    public PlanController(PlanService service, SheetService sheets) {
        this.service = service;
        this.sheets = sheets;
    }

    @GetMapping("/plans")
    public List<PlanView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        String sheet = sheetId.trim();
        LocalDate today = sheets.today(sheet);
        return service.list(sheet).stream().map(plan -> PlanView.of(plan, today)).toList();
    }

    @PostMapping("/people/{personId}/plans")
    @ResponseStatus(HttpStatus.CREATED)
    public PlanView add(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody PlanForm form) {
        String sheet = sheetId.trim();
        return PlanView.of(service.add(sheet, user.trim(), personId, form.amountValue(), form.start(),
                form.everyValue(), form.dayValue(), form.end()), sheets.today(sheet));
    }

    @PostMapping("/plans/{planId}/pause")
    public PlanView pause(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long planId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        String sheet = sheetId.trim();
        return PlanView.of(service.setPaused(sheet, user.trim(), planId, true), sheets.today(sheet));
    }

    @PostMapping("/plans/{planId}/resume")
    public PlanView resume(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long planId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        String sheet = sheetId.trim();
        return PlanView.of(service.setPaused(sheet, user.trim(), planId, false), sheets.today(sheet));
    }

    @PostMapping("/plans/{planId}/amount")
    public PlanView changeAmount(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long planId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody AmountForm form) {
        String sheet = sheetId.trim();
        return PlanView.of(service.changeAmount(sheet, user.trim(), planId, form.amountValue()), sheets.today(sheet));
    }

    @ViewerAllowed
    @PostMapping("/plans/generate")
    public Generated generate(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return new Generated(service.generate(sheetId.trim(), user.trim()));
    }
}
package net.officefloor.hq.app.plan;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OrderColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/** A person's plan: a draft claim of its amount on its start date and every so many days after, or
 *  on a day of every month from the start's month (a day beyond the month's length falling on its
 *  last day, dates before the start left out), up to its end date. */
@Entity
@Table(name = "plan")
public class Plan {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(nullable = false, precision = 14, scale = 2)
    private BigDecimal amount;

    @Column(name = "start_date", nullable = false)
    private LocalDate startDate;

    /** The days it repeats every; null for a monthly plan. */
    @Column(name = "every_days")
    private Integer everyDays;

    /** The day of the month a monthly plan falls on; null for one that repeats every so many days. */
    @Column(name = "month_day")
    private Integer monthDay;

    @Column(name = "end_date", nullable = false)
    private LocalDate endDate;

    /** The plan dates it has made its claim for. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "plan_date", joinColumns = @JoinColumn(name = "plan_id"))
    @Column(name = "on_date", nullable = false)
    private Set<LocalDate> made = new HashSet<>();

    /** The times it was paused; a plan date in one is skipped. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "plan_pause", joinColumns = @JoinColumn(name = "plan_id"))
    private List<PlanPause> pauses = new ArrayList<>();

    /** The changes of its amount, oldest first. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "plan_change", joinColumns = @JoinColumn(name = "plan_id"))
    @OrderColumn(name = "position")
    private List<PlanChange> changes = new ArrayList<>();

    protected Plan() {
    }

    public Plan(String sheetId, Long personId, BigDecimal amount, LocalDate startDate, Integer everyDays,
            Integer monthDay, LocalDate endDate) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.startDate = startDate;
        this.everyDays = everyDays;
        this.monthDay = monthDay;
        this.endDate = endDate;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    /** Make the plan another person's (the one it was for was merged into them). */
    public void setPersonId(Long personId) {
        this.personId = personId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    /** Change the amount the plan's claims take from now on, noting the change on the day given. */
    public void changeAmount(LocalDate on, BigDecimal amount) {
        this.amount = amount;
        changes.add(new PlanChange(on, amount));
    }

    /** The changes of its amount, oldest first. */
    public List<PlanChange> getChanges() {
        return List.copyOf(changes);
    }

    public LocalDate getStartDate() {
        return startDate;
    }

    public Integer getEveryDays() {
        return everyDays;
    }

    public Integer getMonthDay() {
        return monthDay;
    }

    public LocalDate getEndDate() {
        return endDate;
    }

    /** How many claims the plan has made so far. */
    public int getGenerated() {
        return made.size();
    }

    /** The plan dates up to its end and the day given, oldest first, that it has made no claim for
     *  and that no pause skips. */
    public List<LocalDate> dueUpTo(LocalDate today) {
        LocalDate last = endDate.isBefore(today) ? endDate : today;
        List<LocalDate> due = new ArrayList<>();
        if (monthDay != null) {
            for (YearMonth m = YearMonth.from(startDate); !m.atDay(1).isAfter(last); m = m.plusMonths(1)) {
                LocalDate d = m.atDay(Math.min(monthDay, m.lengthOfMonth()));
                if (!d.isBefore(startDate) && !d.isAfter(last) && !made.contains(d) && !skipped(d)) {
                    due.add(d);
                }
            }
            return due;
        }
        for (LocalDate d = startDate; !d.isAfter(last); d = d.plusDays(everyDays)) {
            if (!made.contains(d) && !skipped(d)) {
                due.add(d);
            }
        }
        return due;
    }

    /** The first plan dates after the day given and on or before its end, oldest first, at most as
     *  many as asked for, leaving out those skipped by a pause; none while it is paused. */
    public List<LocalDate> nextAfter(LocalDate today, int count) {
        List<LocalDate> next = new ArrayList<>();
        if (isPaused()) {
            return next;
        }
        if (monthDay != null) {
            for (YearMonth m = YearMonth.from(startDate); next.size() < count && !m.atDay(1).isAfter(endDate);
                    m = m.plusMonths(1)) {
                LocalDate d = m.atDay(Math.min(monthDay, m.lengthOfMonth()));
                if (!d.isBefore(startDate) && d.isAfter(today) && !d.isAfter(endDate) && !skipped(d)) {
                    next.add(d);
                }
            }
            return next;
        }
        LocalDate d = startDate;
        if (d.isBefore(today)) {
            d = d.plusDays((today.toEpochDay() - d.toEpochDay()) / everyDays * everyDays);
        }
        for (; next.size() < count && !d.isAfter(endDate); d = d.plusDays(everyDays)) {
            if (d.isAfter(today) && !skipped(d)) {
                next.add(d);
            }
        }
        return next;
    }

    /** Note that the plan has made its claim for the date. */
    public void markMade(LocalDate date) {
        made.add(date);
    }

    /** Whether the plan is paused and not yet resumed. */
    public boolean isPaused() {
        return pauses.stream().anyMatch(PlanPause::isOpen);
    }

    /** Pause the plan from the day given. */
    public void pause(LocalDate on) {
        pauses.add(new PlanPause(on));
    }

    /** Resume the paused plan on the day given. */
    public void resume(LocalDate on) {
        pauses.stream().filter(PlanPause::isOpen).forEach(p -> p.resume(on));
    }

    /** Whether a pause skips the date. */
    private boolean skipped(LocalDate date) {
        return pauses.stream().anyMatch(p -> p.covers(date));
    }
}
